/* The game profile, as C. GENERATED by nx2/game_profile.py --emit-header: do not edit.
 *
 * Edit nx2/game_profile.py and run `python -I nx2/game_profile.py --emit-header`. The committed copy is
 * checked against that file by tests/test_game_profile.py, so an edit here fails the suite. A lift writes the
 * dump's own profile beside its C, and the build reads that one first.
 *
 * A GAME_HAVE_<x> of 0 means this profile does not know that value. The code it guards must then leave the
 * thing alone rather than guess: an unknown offset is a feature that is off, not a number to invent. */
#ifndef GAME_PROFILE_H
#define GAME_PROFILE_H

/* the project, which is not game data. GAME_PROJECT_W is the same name for the Win32 wide-string calls. */
#define GAME_PROJECT "Lakitu"
#define GAME_PROJECT_W L"Lakitu"

#define GAME_PROFILE_KEY "oot"
#define GAME_NAME "The Legend of Zelda: Ocarina of Time"
#define GAME_PROGRAM_ID "0400486024DEC000"
#define GAME_HAVE_PROGRAM_ID 1
#define GAME_VERSION 131072
#define GAME_HAVE_VERSION 1
/* main's build id: the runtime checks the image it runs against it before it recognises any address */
#define GAME_BUILD_ID "e0f3ccfaf50065ae4ea01eb5aeb13b1a45da3348"
#define GAME_HAVE_BUILD_ID 1

/* main's base in the lifted image */
#define GAME_MAIN_BASE 0x80020000ull
#define GAME_HAVE_MAIN_BASE 1

/* offsets into the game's graphics module (host/nn_vi.c's hos_gfx_module) */
#define GAME_GFX_FRAME_LIMITER 0xfc
#define GAME_GFX_HAVE_FRAME_LIMITER 1
#define GAME_GFX_NOMINAL_FPS 0x2c8
#define GAME_GFX_HAVE_NOMINAL_FPS 1
#define GAME_GFX_VRR_MODE 0x231
#define GAME_GFX_HAVE_VRR_MODE 1
#define GAME_GFX_VRR_GATE 0x232
#define GAME_GFX_HAVE_VRR_GATE 1
#define GAME_GFX_CONTROLLER 0x270
#define GAME_GFX_HAVE_CONTROLLER 1
#define GAME_GFX_CONTROLLER_WORDS { 0x58, 0x28, 0x2c, 0x30 }
#define GAME_GFX_CONTROLLER_WORD_COUNT 4
#define GAME_GFX_CONTROLLER_RATE_WORDS { 0x58, 0x28, 0x2c }
#define GAME_GFX_CONTROLLER_RATE_WORD_COUNT 3

/* return addresses the runtime recognises the game's calls by (host/hos_thread.c, host/nvn_native.c) */
#define GAME_LR_GFX_CLOCK 0x8348c770ull
#define GAME_HAVE_LR_GFX_CLOCK 1
#define GAME_LR_PRESENT_POLL 0x80590520ull
#define GAME_HAVE_LR_PRESENT_POLL 1
#define GAME_LR_PRESENT_EVENTS { 0x805904a0ull, 0x80590530ull }
#define GAME_LR_PRESENT_EVENT_COUNT 2

/* shader program keys this game's renderer treats specially; empty: none of them */
#define GAME_UPSCALE_TAAU_KEYS "fd029a317a9a4b94"
#define GAME_NETWORK_KEEP_KEYS "fd029a317a9a4b94,9dc98871eb7fc101"
#define GAME_GAMEPLAY_NETWORK_KEYS { 0xfd029a317a9a4b94ull, 0x9dc98871eb7fc101ull }
#define GAME_GAMEPLAY_NETWORK_KEY_COUNT 2

/* Npads served when HOS_NPAD_PLAYERS is unset: a count, or -1 for one per attached controller */
#define GAME_NPAD_PLAYERS 1

/* the saves' folder on Linux, under $XDG_DATA_HOME (host/hos_main.c saves_dir): Ocarina's stays where its
   players' saves are, every other game has its own, so no two games ever write one save folder */
#define GAME_SAVES_DIR "hookshot"

/* the console's users (nn::account) when HOS_ACCOUNT_USERS is unset: host/nn_applet.c */
#define GAME_ACCOUNT_USERS 1

#endif /* GAME_PROFILE_H */
